#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ZIP="${1:-$SCRIPT_DIR/Kontakt_8_Installer.zip}"
OUT="${OUT:-/tmp/k8_drive_c}"
TMP="/tmp/k8_extract"

echo "Extracting $ZIP..."
mkdir -p "$TMP"
unzip -qo "$ZIP" -d "$TMP"

echo "Extracting installer exe..."
EXE=$(find "$TMP" -name "*.exe" | head -1)
7z x "$EXE" -o"$TMP" -y > /dev/null

SRC=$(find "$TMP" -type d -name "OFFLINE" | head -1)
echo "OFFLINE dir: $SRC"

# Build filename->path index from OFFLINE tree
declare -A FILE_INDEX
while IFS= read -r -d "" f; do
  name="$(basename "$f")"
  FILE_INDEX["$name"]="$f"
done < <(find "$SRC" -type f -print0)

echo "Installing files..."
MISSING=0
if [[ -n "${FILE_INDEX["Cozy Kit.nkl"]+x}" ]]; then
  mkdir -p "$OUT/Program Files/Common Files/Native Instruments/Kontakt 8/Content/Presets/Lo-Fi Vibes/Kits"
  cp -n "${FILE_INDEX["Cozy Kit.nkl"]}" "$OUT/Program Files/Common Files/Native Instruments/Kontakt 8/Content/Presets/Lo-Fi Vibes/Kits/Cozy Kit.nkl"
else
  echo "MISSING: Cozy Kit.nkl"; ((MISSING++)) || true
fi
if [[ -n "${FILE_INDEX["Cream Soda Kit.nkl"]+x}" ]]; then
  mkdir -p "$OUT/Program Files/Common Files/Native Instruments/Kontakt 8/Content/Presets/Lo-Fi Vibes/Kits"
  cp -n "${FILE_INDEX["Cream Soda Kit.nkl"]}" "$OUT/Program Files/Common Files/Native Instruments/Kontakt 8/Content/Presets/Lo-Fi Vibes/Kits/Cream Soda Kit.nkl"
